```css
:root {
  /* Color Palette */
  --color-primary: #004B8D;      /* Deep Blue */
  --color-secondary: #007A4D;    /* Forest Green */
  --color-accent: #FFC20E;       /* Bright Gold */
  --color-background: #F5F7FA;   /* Light Grayish Blue */
  --color-text-primary: #1B1B1B; /* Almost Black */
  --color-text-secondary: #4A4A4A; /* Dark Gray */
  --color-hero-bg: #E1EDF7;      /* Very Light Blue */
  --color-hero-overlay: rgba(0, 75, 141, 0.1); /* transparent deep blue overlay */
}

.hero {
  background-color: var(--color-hero-bg);
  color: var(--color-text-primary);
  padding: 6rem 2rem;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: flex-start;
  min-height: 80vh;
  position: relative;
  font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
}

.hero::before {
  content: "";
  position: absolute;
  top: 0; left: 0; right: 0; bottom: 0;
  background-color: var(--color-hero-overlay);
  pointer-events: none;
  z-index: 0;
}

.hero > * {
  position: relative;
  z-index: 1;
}
