  --color-text-primary: #1A1A1A; /* Dark Charcoal */
  --color-text-secondary: #555555; /* Medium Gray */
  --color-hero-bg: #E6F0FA;      /* Very Light Blue */
}

.hero {
  background-color: var(--color-hero-bg);
  color: var(--color-text-primary);
  padding: 80px 20px;
  text-align: center;
}

.hero h1 {
  font-size: 3rem;
  font-weight: 700;
  margin-bottom: 20px;
  color: var(--color-primary);
}

.hero p {
  font-size: 1.25rem;
  margin-bottom: 30px;
  color: var(--color-text-secondary);
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
}

.hero .btn-primary {
  background-color: var(--color-secondary);
  color: #fff;
  border: none;
  padding: 15px 40px;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  border-radius: 4px;
  transition: background-color 0.3s ease;
}

.hero .btn-primary:hover {
  background-color: #005c3a; /* Darker green on hover */
}
