  --color-primary: #007B9E;      /* Deep teal blue */
  --color-secondary: #00A3B4;    /* Bright cyan */
  --color-accent: #F2A365;       /* Warm orange */
  --color-background: #F8FAFB;   /* Light grayish blue */
  --color-text-primary: #1B2A41; /* Dark slate blue */
  --color-text-secondary: #4A6B82; /* Steel blue */
  --color-hero-bg: #E6F0F3;      /* Very light blue */
}

.hero {
  background-color: var(--color-hero-bg);
  color: var(--color-text-primary);
  padding: 6rem 2rem;
  text-align: center;
  font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
}

.hero h1 {
  font-size: 3rem;
  margin-bottom: 1rem;
  color: var(--color-primary);
}

.hero p {
  font-size: 1.25rem;
  margin-bottom: 2rem;
  color: var(--color-text-secondary);
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
}

.hero .btn-primary {
  background-color: var(--color-primary);
  color: #ffffff;
  border: none;
  padding: 1rem 2rem;
  font-size: 1.125rem;
  cursor: pointer;
  border-radius: 4px;
  transition: background-color 0.3s ease;
  text-decoration: none;
  display: inline-block;
}

.hero .btn-primary:hover,
.hero .btn-primary:focus {
  background-color: var(--color-secondary);
  outline: none;
}
```

