:root {
  /* Color Definitions */
  --color-primary: #00796b;      /* Teal */
  --color-secondary: #004d40;    /* Dark Teal */
  --color-accent: #00bfa5;       /* Aqua */
  --color-background: #e0f2f1;   /* Light Teal */
  --color-text-primary: #212121; /* Dark Gray */
  --color-text-secondary: #757575; /* Medium Gray */
  --color-button-bg: #004d40;    /* Dark Teal */
  --color-button-text: #ffffff;  /* White */
}

.hero {
  background-color: var(--color-background);
  color: var(--color-text-primary);
  padding: 80px 20px;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  justify-content: center;
  min-height: 600px;
  font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
}

.hero h1 {
  font-size: 3rem;
  margin-bottom: 20px;
  font-weight: 700;
  color: var(--color-primary);
}

.hero p {
  font-size: 1.25rem;
  margin-bottom: 40px;
  color: var(--color-text-secondary);
  max-width: 600px;
}

.hero button {
  background-color: var(--color-button-bg);
  color: var(--color-button-text);
  border: none;
  padding: 15px 30px;
  font-size: 1.1rem;
  font-weight: 600;
  cursor: pointer;
  border-radius: 4px;
  transition: background-color 0.3s ease;
}

.hero button:hover,
.hero button:focus {
  background-color: var(--color-accent);
  outline: none;
}
```

```css
:root {
  /* Color Definitions */
  --color-primary: #00796b;      /* Teal */
  --color-secondary: #004d40;    /* Dark Teal */
  --color-accent: #00bfa5;       /* Bright Teal */
  --color-background: #e0f2f1;   /* Light Mint */
  --color-text-primary: #263238; /* Charcoal */
  --color-text-secondary: #546e7a; /* Slate Gray */
  --color-white: #ffffff;
  --color-error: #d32f2f;        /* Red for alerts/errors */
}

.hero {
  background-color: var(--color-background);
  color: var(--color-text-primary);
  padding: 4rem 2rem;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  min-height: 60vh;
  font-family: "Segoe UI", Tahoma, Geneva, Verdana, sans-serif;
}

.hero h1 {
  font-size: 3rem;
  margin-bottom: 1rem;
  font-weight: 700;
}

.hero p {
  font-size: 1.25rem;
  max-width: 600px;
  margin: 0 auto;
  color: var(--color-text-secondary);
}

.hero button {
  margin-top: 2rem;
  background-color: var(--color-primary);
  color: var(--color-white);
  border: none;
  padding: 0.75rem 2rem;
  font-size: 1.1rem;
  border-radius: 0.375rem;
  cursor: pointer;
  transition: background-color 0.3s ease;
}

.hero button:hover,
.hero button:focus {
  background-color: var(--color-accent);
  outline: none;
}
```

