  color: var(--color-hero-text);
  padding: 6rem 2rem;
  text-align: center;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  min-height: 60vh;
  font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
}

.hero h1 {
  font-size: 3rem;
  margin-bottom: 1rem;
  font-weight: 700;
}

.hero p {
  font-size: 1.25rem;
  max-width: 600px;
  margin-bottom: 2rem;
  color: var(--color-hero-text);
}

.hero .btn-primary {
  background-color: var(--color-secondary);
  color: var(--color-hero-text);
  border: none;
  padding: 1rem 2rem;
  font-size: 1.1rem;
