  font-weight: 700;
  color: var(--color-text-primary);
}

.hero p {
  font-size: 1.25rem;
  margin-bottom: 2rem;
  color: var(--color-text-secondary);
  max-width: 600px;
}

.hero .btn-primary {
  background-color: var(--color-hero-button-bg);
