  --primary-color: #007bff; /* A vibrant blue for primary actions and highlights */
  --secondary-color: #6c757d; /* A muted gray for secondary text or borders */
  --accent-color: #28a745; /* A bright green for success states or call to actions */
  --text-color: #343a40; /* Dark charcoal for general body text */
  --heading-color: #212529; /* Even darker for headings */
  --background-color-light: #f8f9fa; /* A very light gray for general backgrounds */
  --background-color-dark: #e9ecef; /* A slightly darker gray for subtle contrast */
  --white: #ffffff;
  --black: #000000;

  /* Spacing */
  --spacing-xs: 0.25rem;
  --spacing-sm: 0.5rem;
  --spacing-md: 1rem;
  --spacing-lg: 1.5rem;
  --spacing-xl: 2rem;
  --spacing-xxl: 3rem;

  /* Typography */
  --font-family-sans: 'Inter', sans-serif; /* Example: Google Fonts */
  --font-family-serif: 'Merriweather', serif; /* Example: Google Fonts */
  --font-size-base: 1rem;
  --font-size-lg: 1.25rem;
  --font-size-xl: 1.5rem;
  --font-size-h1: 3rem;
  --font-size-h2: 2.25rem;
  --font-size-h3: 1.75rem;

  /* Border Radius */
  --border-radius-sm: 0.25rem;
  --border-radius-md: 0.5rem;
  --border-radius-lg: 0.75rem;

  /* Box Shadow */
  --box-shadow-sm: 0 0.125rem 0.25rem rgba(0, 0, 0, 0.075);
  --box-shadow-md: 0 0.25rem 0.75rem rgba(0, 0, 0, 0.1);
}

/* Hero Section Styles */
.hero-section {
  background-color: var(--background-color-dark); /* Solid background color for the hero */
  color: var(--heading-color); /* Default text color for hero content */
  padding: var(--spacing-xxl) 0; /* Top and bottom padding */
  text-align: center; /* Center align content */
  position: relative; /* Needed for potential pseudo-elements or absolute positioning */
  overflow: hidden; /* Hide any overflowing background elements */
}

.hero-section::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background-color: var(--background-color-light); /* Another solid color for a subtle layer */
  opacity: 0.3; /* Make it semi-transparent */
  z-index: 1; /* Place it above the main background, but below content */
}

.hero-section-content {
  position: relative; /* Ensure content is above pseudo-elements */
  z-index: 2;
  max-width: 960px; /* Limit content width */
  margin: 0 auto; /* Center content horizontally */
  padding: 0 var(--spacing-md); /* Add horizontal padding */
}

.hero-section h1 {
  font-family: var(--font-family-sans);
