/* CSS Variables */
:root {
  /* Primary Colors */
  --color-primary-dark: #004d40; /* Dark Teal */
  --color-primary-medium: #00796b; /* Medium Teal */
  --color-primary-light: #4db6ac; /* Light Teal */

  /* Accent Colors */
  --color-accent-dark: #ff6f00; /* Dark Orange */
  --color-accent-medium: #ffa000; /* Medium Orange */
  --color-accent-light: #ffeb3b; /* Bright Yellow */

  /* Neutral Colors */
  --color-text-dark: #212121; /* Dark Gray */
  --color-text-light: #f5f5f5; /* Off-White */
  --color-background-light: #ffffff; /* Pure White */
  --color-background-dark: #303030; /* Dark Gray Background */
  --color-border: #bdbdbd; /* Light Gray Border */

  /* Typography */
  --font-family-heading: 'Poppins', sans-serif;
  --font-family-body: 'Roboto', sans-serif;
  --font-size-hero-title: 3.5rem; /* ~56px */
  --font-size-hero-subtitle: 1.5rem; /* ~24px */
  --font-size-button: 1.1rem; /* ~18px */

  /* Spacing */
  --spacing-unit: 0.5rem; /* 8px base unit */
  --spacing-small: var(--spacing-unit);
  --spacing-medium: calc(var(--spacing-unit) * 2); /* 16px */
  --spacing-large: calc(var(--spacing-unit) * 4); /* 32px */
  --spacing-hero-padding: 6rem 0; /* Top/Bottom padding for hero */

  /* Border Radius */
  --border-radius-small: 4px;
  --border-radius-medium: 8px;

  /* Box Shadow */
  --box-shadow-light: 0 4px 8px rgba(0, 0, 0, 0.1);
  --box-shadow-medium: 0 8px 16px rgba(0, 0, 0, 0.2);
}

/* Hero Section Styles */
.hero-section {
  background-color: var(--color-background-dark); /* Dark background for contrast */
  color: var(--color-text-light); /* Light text on dark background */
  padding: var(--spacing-hero-padding);
  text-align: center;
  min-height: 80vh; /* Ensure hero takes up a good portion of the viewport */
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  position: relative; /* For potential background images/elements */
  overflow: hidden; /* Hide anything that overflows */
}

.hero-content {
  max-width: 900px;
  margin: 0 auto;
  z-index: 1; /* Ensure content is above any background effects */
  position: relative;
}

.hero-title {
  font-family: var(--font-family-heading);
  font-size: var(--font-size-hero-title);
  font-weight: 700;
  margin-bottom: var(--spacing-medium);
  line-height: 1.2;
  color: var(--color-primary-light); /* Use a primary color for the title */
}

.hero-subtitle {
  font-family: var(--font-family-body);
  font-size: var(--font-size-hero-subtitle);
  font-weight: 300;
  margin-bottom: var(--spacing-large);
  line-height: 1.5;
  color: var(--color-text-light);
}

.hero-buttons {
  display: flex;
  justify-content: center;
  gap: var(--spacing-medium);
}

.hero-button {
  display: inline-block;
  padding: var(--spacing-small) var(--spacing-large);
  border-radius: var(--border-radius-medium);

