    --color-neutral-offwhite: #F8F8F8;
    --color-neutral-lightgray: #E0E0E0;
    --color-neutral-gray: #808080;
    --color-neutral-darkgray: #333333;
    --color-neutral-black: #000000;

    /* Text Colors */
    --color-text-primary: var(--color-neutral-darkgray);
    --color-text-secondary: var(--color-neutral-gray);
    --color-text-hero: var(--color-neutral-white);

    /* Border Colors */
    --color-border-light: var(--color-neutral-lightgray);
    --color-border-dark: var(--color-neutral-gray);

    /* Spacing */
    --spacing-xs: 4px;
    --spacing-sm: 8px;
    --spacing-md: 16px;
