    --color-primary-dark: #0056b3; /* Darker shade for hover/active */
    --color-secondary: #28a745; /* A vibrant green for accents/success */
    --color-secondary-dark: #1e7e34; /* Darker green */
    --color-accent: #ffc107; /* A bright yellow for highlights/warnings */
    --color-accent-dark: #e0a800; /* Darker yellow */
    --color-text-dark: #343a40; /* Dark gray for main body text */
    --color-text-light: #f8f9fa; /* Off-white for text on dark backgrounds */
    --color-background-light: #ffffff; /* Pure white for light backgrounds */
    --color-background-dark: #212529; /* Dark gray for dark sections */
    --color-border: #dee2e6; /* Light gray for borders */

    /* Typography */
    --font-family-sans-serif: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol";
