    --font-size-lg: 1.25rem;
    --font-size-sm: 0.875rem;

    --heading-font-weight: 700;

    /* Spacing */
    --spacing-xs: 0.25rem;
    --spacing-sm: 0.5rem;
    --spacing-md: 1rem;
    --spacing-lg: 1.5rem;
    --spacing-xl: 3rem;

    /* Border Radius */
    --border-radius-sm: 0.25rem;
    --border-radius-md: 0.5rem;
}

/* Hero Section Styles */
.hero-section {
    background-color: var(--color-background-dark); /* Dark background for a strong presence */
    color: var(--color-text-light); /* Light text on dark background */
    padding: var(--spacing-xl) 0; /* Vertical padding */
    text-align: center; /* Center align content */
    position: relative; /* Needed for any potential absolute positioning of elements inside */
    overflow: hidden; /* Hide anything that overflows */
}

/* Optional: Subtle background pattern for the hero */
.hero-section::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    /* A subtle, almost transparent pattern using a SVG data URI or a very light solid color */
