:root {
  /* Primary Colors */
  --color-primary-dark: #004080; /* Deep Ocean Blue */
  --color-primary-medium: #0056b3; /* Classic Blue */
  --color-primary-light: #007bff; /* Bright Blue */

  /* Secondary/Accent Colors */
  --color-accent-gold: #ffc107; /* Golden Yellow */
  --color-accent-teal: #20c997; /* Teal Green */

  /* Neutral Colors */
  --color-text-dark: #212529; /* Dark Grey */
  --color-text-medium: #495057; /* Medium Grey */
  --color-text-light: #6c757d; /* Light Grey */
  --color-background-light: #f8f9fa; /* Off-White */
  --color-background-dark: #343a40; /* Dark Grey Background */
  --color-border: #dee2e6; /* Light Grey Border */
  --color-white: #ffffff; /* Pure White */
  --color-black: #000000; /* Pure Black */

  /* Font Sizes (Example) */
  --font-size-h1: 3.5rem;
  --font-size-h2: 2.5rem;
  --font-size-h3: 1.75rem;
  --font-size-body: 1rem;
  --font-size-small: 0.875rem;

  /* Spacing (Example) */
  --spacing-xxs: 0.25rem;
  --spacing-xs: 0.5rem;
  --spacing-sm: 1rem;
  --spacing-md: 1.5rem;
  --spacing-lg: 2rem;
  --spacing-xl: 3rem;
  --spacing-xxl: 4rem;

  /* Border Radius */
  --border-radius-sm: 0.25rem;
  --border-radius-md: 0.5rem;
  --border-radius-lg: 0.75rem;

  /* Box Shadow */
  --box-shadow-sm: 0 0.125rem 0.25rem rgba(0, 0, 0, 0.075);
  --box-shadow-md: 0 0.5rem 1rem rgba(0, 0, 0, 0.15);
}

/* Hero Section Styles */
.hero-section {
  position: relative;
  width: 100%;
  min-height: 70vh; /* Adjust as needed */
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  color: var(--color-white); /* Text color for hero content */
  overflow: hidden; /* Ensures background image doesn't overflow */

  /* Background Styling */
  background-color: var(--color-primary-dark); /* Solid background color as fallback */
  background-image: url('path/to/your/hero-background-image.jpg'); /* Replace with your image path */
  background-size: cover; /* Cover the entire hero section */
  background-position: center center; /* Center the background image */
  background-repeat: no-repeat; /* Do not repeat the background image */
}

/* Optional: Overlay for better text readability on image */
.hero-section::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background-color: rgba(0, 64, 128, 0.7); /* Dark blue overlay with transparency */
  z-index: 1; /* Place overlay above background image, below content */
}

.hero-content {
  position: relative;
  z-index: 2; /* Ensure content is above the overlay */
  max-width: 900px; /* Max width for content to prevent stretching */
  padding: var(--spacing-lg) var(--spacing-md);
  margin: 0 auto;
}

