/* CSS Variables for Financial Services Company */
:root {
  /* Primary Colors - Professional and Trustworthy */
  --primary-color: #0056b3; /* A strong, classic blue */
  --primary-color-dark: #003d82; /* Darker shade for hover/active states */
  --primary-color-light: #e0f2ff; /* Very light blue for subtle backgrounds */

  /* Secondary Colors - Complementary and Engaging */
  --secondary-color: #28a745; /* A vibrant, reassuring green */
  --secondary-color-dark: #1e7e34; /* Darker green */
  --secondary-color-light: #d4edda; /* Light green for accents */

  /* Neutral Colors - Readability and Structure */
  --text-color-dark: #333333; /* Dark gray for primary text */
  --text-color-light: #6c757d; /* Lighter gray for secondary text/subheadings */
  --background-color-light: #f8f9fa; /* Off-white for general backgrounds */
  --background-color-dark: #e9ecef; /* Slightly darker off-white for sections */
  --border-color: #dee2e6; /* Light gray for borders and separators */
  --white: #ffffff; /* Pure white */
  --black: #000000; /* Pure black */

  /* Accent/Highlight Color - For calls to action or important elements */
  --accent-color: #ffc107; /* A bright, energetic yellow/gold */
  --accent-color-dark: #e0a800; /* Darker yellow for hover */

  /* Font Families */
  --font-primary: 'Arial', sans-serif;
  --font-secondary: 'Georgia', serif;

  /* Font Sizes */
  --font-size-h1: 3.5rem;
  --font-size-h2: 2.5rem;
  --font-size-h3: 1.75rem;
  --font-size-body: 1rem;
  --font-size-small: 0.875rem;

  /* Spacing */
  --spacing-xs: 0.25rem;
  --spacing-sm: 0.5rem;
  --spacing-md: 1rem;
  --spacing-lg: 1.5rem;
  --spacing-xl: 2rem;
  --spacing-xxl: 3rem;

  /* Border Radius */
  --border-radius-sm: 4px;
  --border-radius-md: 8px;
  --border-radius-lg: 12px;
}

/* Hero Section Styles */
.hero-section {
  background-color: var(--primary-color-dark); /* Dark blue background */
  color: var(--white); /* White text for contrast */
  padding: var(--spacing-xxl) var(--spacing-lg); /* Ample padding top/bottom and sides */
  text-align: center;
  position: relative; /* For potential absolute positioning of elements inside */
  overflow: hidden; /* To contain any background elements if added later */
}

.hero-section::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  /* Subtle overlay pattern or texture - using a solid color for simplicity as per constraint */
  background-color: rgba(0, 0, 0, 0.1); /* A very subtle dark overlay for depth */
  z-index: 1; /* Ensure it's behind content but above the base background */
}

.hero-content {
  position: relative; /* Position content above the ::before pseudo-element */
  z-index: 2;
  max-width: 900px; /* Limit content width for readability */
  margin: 0 auto; /* Center the content */
}

.hero-section h1 {
  font-family: var(--font-primary);
  font-size: var(--font-size-h1);
  font-weight: bold;
  margin-bottom: var(--spacing-md);
  line-height: 1.2;
}

