/* CSS Variables */
:root {
  /* Colors */
  --color-primary: #007BFF; /* A vibrant blue, common in healthcare */
  --color-secondary: #28A745; /* A calming green for accents/success */
  --color-accent: #FFC107; /* A warm yellow for highlights/warnings */
  --color-text-dark: #343A40; /* Dark gray for primary text */
  --color-text-light: #6C757D; /* Lighter gray for secondary text */
  --color-background-light: #F8F9FA; /* Off-white for general backgrounds */
  --color-background-dark: #E9ECEF; /* Slightly darker background for sections */
  --color-white: #FFFFFF; /* Pure white */

  /* Typography */
  --font-family-sans-serif: 'Arial', sans-serif;
  --font-family-serif: 'Georgia', serif;
  --font-size-base: 16px;
  --line-height-base: 1.6;

  /* Spacing */
  --spacing-xs: 0.5rem;
  --spacing-sm: 1rem;
  --spacing-md: 1.5rem;
  --spacing-lg: 2rem;
  --spacing-xl: 3rem;

  /* Border Radius */
  --border-radius-sm: 0.25rem;
  --border-radius-md: 0.5rem;
}

/* Hero Section Styles */
.hero-section {
  background-color: var(--color-background-light); /* Off-white background */
  background-image: url('path/to/your/hero-background-image.jpg'); /* Replace with your image */
  background-position: center center;
  background-repeat: no-repeat;
  background-size: cover; /* Ensures the image covers the entire hero area */
  color: var(--color-text-dark); /* Default text color for the hero */
  padding: var(--spacing-xl) 0; /* Vertical padding */
  text-align: center; /* Center align content */
  position: relative; /* Needed for overlay */
  overflow: hidden; /* Prevent background image overflow */
}

/* Optional: Add an overlay for better text readability on busy backgrounds */
.hero-section::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background-color: rgba(248, 249, 250, 0.7); /* Semi-transparent off-white overlay */
  z-index: 1; /* Place overlay above background image */
}

.hero-section .hero-content {
  position: relative; /* Place content above the overlay */
  z-index: 2;
  max-width: 960px; /* Limit content width */
  margin: 0 auto; /* Center content horizontally */
  padding: var(--spacing-md);
}

.hero-section h1 {
  font-family: var(--font-family-sans-serif);
  font-size: 3rem; /* Large heading for impact */
  color: var(--color-primary); /* Primary blue for the main heading */
  margin-bottom: var(--spacing-sm);
  line-height: 1.2;
}

.hero-section p {
  font-family: var(--font-family-sans-serif);
  font-size: var(--font-size-base);
  color: var(--color-text-dark);
