    --color-white: #ffffff; /* Pure white */
    --color-black: #000000; /* Pure black */

    /* Feedback/Alert Colors (not used in hero, but good to have) */
    --color-success: #28a745; /* Same as secondary, often used for success messages */
    --color-warning: #ffc107; /* Bright yellow for warnings */
    --color-danger: #dc3545; /* Red for errors or critical actions */

    /* Font Families */
    --font-heading: 'Montserrat', sans-serif; /* Modern, clean sans-serif for headings */
    --font-body: 'Open Sans', sans-serif;     /* Readable sans-serif for body text */

    /* Spacing */
    --spacing-xs: 0.25rem;
    --spacing-sm: 0.5rem;
    --spacing-md: 1rem;
    --spacing-lg: 1.5rem;
    --spacing-xl: 2rem;
    --spacing-xxl: 3rem;

    /* Border Radius */
    --border-radius-sm: 0.25rem;
    --border-radius-md: 0.5rem;
}

/* Hero Section Styles */
.hero-section {
    position: relative;
    display: flex;
    align-items: center; /* Vertically center content */
    justify-content: center; /* Horizontally center content */
    min-height: 500px; /* Minimum height for the hero section */
    padding: var(--spacing-xxl) var(--spacing-md);
    text-align: center;
    overflow: hidden; /* Ensure background doesn't overflow */

    /* Background Styling */
    background-color: var(--color-primary-light); /* Light blue background for a fresh feel */
    background-image: url('path/to/your/hero-background-image.jpg'); /* Replace with your actual image path */
    background-size: cover; /* Cover the entire hero section */
    background-position: center center; /* Center the background image */
    background-repeat: no-repeat; /* Do not repeat the background image */

    /* Optional: Overlay for better text readability on image backgrounds */
