/* CSS Variables */
:root {
  /* Primary Colors */
  --color-primary: #007bff; /* A standard blue, often used for links/buttons */
  --color-primary-dark: #0056b3; /* Darker shade of primary for hover/active states */
  --color-primary-light: #e0f2ff; /* Lighter shade for backgrounds or accents */

  /* Secondary Colors (often for accents or complementary elements) */
  --color-secondary: #28a745; /* A vibrant green for success/positive actions */
  --color-secondary-dark: #1e7e34;
  --color-secondary-light: #d4edda;

  /* Neutral Colors (for text, backgrounds, borders) */
  --color-text-dark: #343a40; /* Dark grey for main body text */
  --color-text-medium: #6c757d; /* Medium grey for secondary text */
  --color-text-light: #f8f9fa; /* Very light grey, often for text on dark backgrounds */
  --color-background-light: #f8f9fa; /* Light grey for general page backgrounds */
  --color-background-medium: #e9ecef; /* Slightly darker grey for sections */
  --color-border: #dee2e6; /* Light grey for borders */

  /* Alert/Status Colors (ensure they don't clash with primary/secondary) */
  --color-success: #28a745; /* Green (same as secondary for consistency) */
  --color-warning: #ffc107; /* Amber/Yellow for warnings */
  --color-danger: #dc3545; /* Red for errors/alerts */
  --color-info: #17a2b8; /* Cyan for informational messages */

  /* Font Families */
  --font-family-sans-serif: 'Helvetica Neue', Helvetica, Arial, sans-serif;
  --font-family-serif: 'Georgia', serif;
  --font-family-monospace: 'SFMono-Regular', Consolas, 'Liberation Mono', Menlo, Courier, monospace;

  /* Spacing */
  --spacing-xs: 0.25rem;
  --spacing-sm: 0.5rem;
  --spacing-md: 1rem;
  --spacing-lg: 1.5rem;
  --spacing-xl: 3rem;

  /* Border Radius */
  --border-radius-sm: 0.25rem;
  --border-radius-md: 0.5rem;
  --border-radius-lg: 1rem;
}

/* Hero Section Styles */
.hero-section {
  /* Background Styling */
  background-color: var(--color-background-light); /* A light, clean background */
  background-image: url('path/to/your/hero-image.jpg'); /* Replace with your actual image path */
  background-repeat: no-repeat;
  background-position: center center; /* Center the image */
  background-size: cover; /* Cover the entire hero section */

  /* Optional: Add an overlay for better text readability on top of the image */
  position: relative; /* Needed for absolute positioning of the overlay */
  overflow: hidden; /* Ensures overlay doesn't spill out */

  /* Padding and Height */
  padding: var(--spacing-xl) var(--spacing-md); /* Top/bottom, left/right padding */
  min-height: 500px; /* Minimum height for the hero section */
  display: flex; /* Use flexbox for content alignment */
  align-items: center; /* Vertically center content */
  justify-content: center; /* Horizontally center content */
  text-align: center; /* Center text within the hero content */
}

/* Hero Overlay (if needed for text readability) */
