:root {
    /* Primary Colors */
    --primary-color: #007BFF; /* A vibrant blue, often used for buttons, links, and key actions */
    --primary-light: #66B3FF; /* Lighter shade of primary for hover states or secondary accents */
    --primary-dark: #0056B3;  /* Darker shade of primary for active states or strong emphasis */

    /* Secondary Colors (often for complementary elements, alerts, or less critical actions) */
    --secondary-color: #28A745; /* A fresh green, good for success messages or eco-friendly themes */
    --secondary-light: #6EE58B; /* Lighter green */
    --secondary-dark: #1E7E34;  /* Darker green */

    /* Neutral Colors (for text, backgrounds, borders) */
