:root {
    /* Primary Colors */
    --primary-blue: #2196F3; /* A standard, vibrant blue */
    --primary-dark-blue: #1976D2; /* A darker shade for accents/hover */

    /* Accent Colors */
    --accent-green: #4CAF50; /* A friendly, inviting green */
    --accent-dark-green: #388E3C; /* A darker shade for accents/hover */
    --accent-orange: #FF9800; /* A bright, energetic orange for CTAs */

    /* Neutral Colors */
    --neutral-white: #FFFFFF;
    --neutral-light-gray: #F5F5F5;
    --neutral-gray: #E0E0E0;
    --neutral-dark-gray: #757575;
    --neutral-black: #212121;

    /* Text Colors */
    --text-primary: var(--neutral-black);
    --text-secondary: var(--neutral-dark-gray);
    --text-on-primary: var(--neutral-white); /* For text on primary blue backgrounds */
    --text-on-dark: var(--neutral-white); /* For text on dark backgrounds */

