    overflow: hidden; /* Hide any overflow if elements go beyond bounds */
}

.hero-content {
    max-width: 800px; /* Limit content width for better readability */
    margin: 0 auto; /* Center the content block */
    padding: var(--spacing-md); /* Internal padding */
}

.hero-section h1 {
    font-size: var(--font-size-h1);
    margin-bottom: var(--spacing-md);
    line-height: 1.2;
}

.hero-section p {
    font-size: var(--font-size-h3);
    margin-bottom: var(--spacing-lg);
    max-width: 600px;
    margin-left: auto;
    margin-right: auto;
}

.hero-section .btn {
    display: inline-block;
    background-color: var(--color-brand-accent); /* Use accent color for buttons */
    color: var(--color-neutral-dark); /* Dark text on accent button */
    padding: var(--spacing-sm) var(--spacing-lg);
    border-radius: var(--border-radius-sm);
    text-decoration: none;
    font-weight: bold;
    transition: background-color 0.3s ease;
    border: none; /* Ensure no default button border */
    cursor: pointer;
}

.hero-section .btn:hover {
    background-color: #e0a800; /* Slightly darker yellow on hover */
}

.hero-section .btn + .btn {
    margin-left: var(--spacing-md); /* Space between multiple buttons */
}
