:root {
  /* --- Color Palette --- */
  --color-primary: #007bff; /* A vibrant blue for primary actions and highlights */
  --color-secondary: #28a745; /* A strong green for success states or alternative actions */
  --color-accent: #ffc107; /* A bright yellow for warnings, emphasis, or calls to action */
  --color-text-dark: #343a40; /* Dark gray for primary text */
  --color-text-light: #f8f9fa; /* Off-white for text on dark backgrounds */
  --color-background-light: #ffffff; /* Pure white for light backgrounds */
  --color-background-dark: #212529; /* Dark charcoal for dark sections */
  --color-border: #dee2e6; /* Light gray for borders and separators */

  /* --- Spacing --- */
  --spacing-xs: 0.25rem;
  --spacing-sm: 0.5rem;
  --spacing-md: 1rem;
  --spacing-lg: 1.5rem;
  --spacing-xl: 2rem;
  --spacing-xxl: 3rem;

  /* --- Typography --- */
  --font-family-sans-serif: 'Helvetica Neue', Helvetica, Arial, sans-serif;
  --font-family-serif: 'Georgia', serif;
  --font-size-base: 1rem; /* 16px */
  --font-size-h1: 2.5rem;
  --font-size-h2: 2rem;
  --font-size-h3: 1.75rem;
  --font-size-h4: 1.5rem;
  --font-size-h5: 1.25rem;
  --font-size-h6: 1rem;
  --font-weight-light: 300;
  --font-weight-normal: 400;
  --font-weight-bold: 700;
  --line-height-base: 1.6;

  /* --- Border Radius --- */
  --border-radius-sm: 0.25rem;
  --border-radius-md: 0.5rem;
  --border-radius-lg: 0.75rem;

  /* --- Box Shadows --- */
  --box-shadow-sm: 0 0.125rem 0.25rem rgba(0, 0, 0, 0.075);
  --box-shadow-md: 0 0.5rem 1rem rgba(0, 0, 0, 0.15);
}

/* --- Hero Section Styles --- */
.hero-section {
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  text-align: center;
  min-height: 80vh; /* Occupy at least 80% of the viewport height */
  padding: var(--spacing-xxl) var(--spacing-lg);
  background-color: var(--color-background-dark); /* Solid dark background */
  color: var(--color-text-light); /* Light text on dark background */
  position: relative; /* For potential absolute positioning of elements inside */
  overflow: hidden; /* Hide anything that overflows */
}

/* Optional: Overlay for texture or pattern (no gradients) */
.hero-section::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background-image: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" width="4" height="4" viewBox="0 0 4 4"><rect fill="%232e3338" x="0" y="0" width="2" height="2"/><rect fill="%232e3338" x="2" y="2" width="2" height="2"/></svg>');
  background-repeat: repeat;
  opacity: 0.1; /* Subtle pattern effect */
  z-index: 1;
}

