:root {
    /* Primary Color Palette (Blues & Greens) */
    --color-primary-dark: #004d7a;   /* Deep Ocean Blue */
    --color-primary-base: #007bff;   /* Vibrant Sky Blue */
    --color-primary-light: #66c2ff;  /* Light Azure */

    /* Secondary Color Palette (Warm Neutrals & Accents) */
    --color-secondary-dark: #cc6600; /* Burnt Orange */
    --color-secondary-base: #ff9900; /* Bright Orange */
    --color-secondary-light: #ffcc66;/* Muted Gold */

    /* Neutral Colors */
    --color-neutral-dark: #333333;   /* Charcoal */
    --color-neutral-base: #666666;   /* Medium Gray */
    --color-neutral-light: #cccccc;  /* Light Gray */
    --color-neutral-extra-light: #f8f9fa; /* Off-White */
    --color-white: #ffffff;         /* Pure White */
    --color-black: #000000;         /* Pure Black */

    /* Text Colors */
