    --color-accent-light: #FFECB3; /* Pale Gold */

    /* Neutral Colors */
    --color-text-dark: #212121; /* Dark Gray */
    --color-text-medium: #424242; /* Medium Gray */
    --color-text-light: #757575; /* Light Gray */
    --color-background-light: #F5F5F5; /* Very Light Gray */
    --color-background-white: #FFFFFF; /* White */
    --color-border: #E0E0E0; /* Light Border Gray */

    /* Font Sizes */
    --font-size-h1: 3.5rem;
